"use client";

import { cn } from "@/lib/utils";
import { ClockIcon, PlusIcon } from "@/components/icons";
import { SCHEDULED_TASKS } from "@/lib/mock-data";
import type { ScheduledTask } from "@/types";

function Toggle({ on }: { on: boolean }) {
  return (
    <span
      className={cn(
        "relative inline-flex h-5 w-9 items-center rounded-full transition-colors",
        on ? "bg-accent-blue" : "bg-bg-4",
      )}
    >
      <span
        className={cn(
          "inline-block h-4 w-4 rounded-full bg-white transition-transform",
          on ? "translate-x-4" : "translate-x-0.5",
        )}
      />
    </span>
  );
}

function TaskRow({ task }: { task: ScheduledTask }) {
  return (
    <div className="flex items-center gap-4 rounded-[12px] border border-border-base bg-bg-2/50 p-4 transition-colors hover:border-border-special">
      <span className="grid h-10 w-10 shrink-0 place-items-center rounded-[10px] bg-bg-3 text-[18px]">
        {task.emoji}
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate text-[15px] font-medium text-fg">{task.title}</p>
        <div className="mt-0.5 flex flex-wrap items-center gap-x-3 gap-y-1 text-[13px] text-fg-muted">
          <span className="flex items-center gap-1">
            <ClockIcon size={13} />
            {task.schedule}
          </span>
          <span>·</span>
          <span>Next: {task.nextRun}</span>
          <span>·</span>
          <span>{task.assistant}</span>
        </div>
      </div>
      <Toggle on={task.enabled} />
    </div>
  );
}

export function ScheduledScreen() {
  return (
    <div className="h-full overflow-y-auto p-5">
      <div className="mx-auto max-w-[840px]">
        <div className="flex items-center justify-between">
          <h1 className="text-[20px] font-semibold text-fg">Scheduled Tasks</h1>
          <button
            type="button"
            className="flex h-8 items-center gap-1.5 rounded-[8px] border border-border-base px-3 text-[13px] text-fg-secondary transition-colors hover:border-border-special hover:bg-bg-hover hover:text-fg"
          >
            <PlusIcon size={13} />
            New Task
          </button>
        </div>
        <div className="mt-5 flex flex-col gap-3">
          {SCHEDULED_TASKS.map((t) => (
            <TaskRow key={t.id} task={t} />
          ))}
        </div>
      </div>
    </div>
  );
}
