"use client";

import { cn } from "@/lib/utils";
import { GlobeIcon, LogoIcon, MessageIcon, PlusIcon, StarIcon } from "@/components/icons";
import { AGENT_BACKENDS, ASSISTANTS } from "@/lib/mock-data";
import type { Assistant } from "@/types";
import { Composer } from "../Composer";

function BackendGlyph({ id, glyph }: { id: string; glyph: string }) {
  if (id === "aion") {
    return (
      <span className="flex h-6 w-6 items-center justify-center rounded-full bg-[#1c1c1e] text-white">
        <LogoIcon size={15} />
      </span>
    );
  }
  const colors: Record<string, string> = {
    claude: "#d97757",
    codex: "#e6e6e6",
    gemini: "#4285f4",
    copilot: "#e6e6e6",
    qwen: "#a855f7",
    iflow: "#f5455c",
  };
  return (
    <span
      className="flex h-6 w-6 items-center justify-center text-[14px] leading-none"
      style={{ color: colors[id] }}
    >
      {glyph || "●"}
    </span>
  );
}

function PillBar() {
  return (
    <div className="flex items-center gap-0.5 rounded-full border border-border-base bg-bg-2 px-1.5 py-1.5">
      <button
        type="button"
        className="flex items-center gap-2 rounded-full bg-bg-active py-1 pl-1 pr-3 text-[13px] font-medium text-fg"
      >
        <BackendGlyph id="aion" glyph="logo" />
        <span>Aion CLI</span>
      </button>
      {AGENT_BACKENDS.slice(1).map((b) => (
        <div key={b.id} className="flex items-center">
          <span className="mx-0.5 h-4 w-px bg-border-base" />
          <button
            type="button"
            aria-label={b.name}
            title={b.name}
            className="flex h-8 w-8 items-center justify-center rounded-full hover:bg-bg-hover"
          >
            <BackendGlyph id={b.id} glyph={b.glyph} />
          </button>
        </div>
      ))}
      <span className="mx-0.5 h-4 w-px bg-border-base" />
      <button
        type="button"
        aria-label="Add backend"
        className="flex h-8 w-8 items-center justify-center rounded-full text-fg-secondary hover:bg-bg-hover hover:text-fg"
      >
        <PlusIcon size={14} />
      </button>
    </div>
  );
}

function AssistantCard({ a }: { a: Assistant }) {
  return (
    <button
      type="button"
      className="flex items-center gap-3 rounded-[12px] border border-border-base bg-bg-2/50 p-3 text-left transition-colors hover:border-border-special hover:bg-bg-hover"
    >
      <span
        className="grid h-10 w-10 shrink-0 place-items-center rounded-[10px] text-[18px]"
        style={{ background: a.tile }}
      >
        {a.emoji}
      </span>
      <span className="min-w-0 flex-1">
        <span className="block truncate text-[14px] font-semibold text-fg">
          {a.name}
        </span>
        <span className="block truncate text-[13px] text-fg-muted">
          {a.description}
        </span>
      </span>
    </button>
  );
}

function FloatingFooter() {
  const items = [
    { icon: <MessageIcon size={18} />, label: "Report Issue", hover: "hover:text-[#2C7FFF]" },
    { icon: <StarIcon size={18} />, label: "Give us a star", hover: "hover:text-[#FE9900]" },
    { icon: <GlobeIcon size={18} />, label: "Remote", hover: "hover:text-fg" },
  ];
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-5 flex justify-center">
      <div className="pointer-events-auto flex items-center gap-3">
        {items.map((it) => (
          <button
            key={it.label}
            type="button"
            aria-label={it.label}
            title={it.label}
            className={cn(
              "flex h-9 w-9 items-center justify-center rounded-full border border-border-base bg-bg-2 text-fg-muted transition-colors",
              it.hover,
            )}
          >
            {it.icon}
          </button>
        ))}
      </div>
    </div>
  );
}

export function HomeScreen() {
  return (
    <div className="relative flex h-full flex-col">
      <div className="flex-1 overflow-y-auto">
        <div className="mx-auto flex min-h-full w-full max-w-[840px] flex-col items-center px-6 pb-28 pt-[13vh]">
          <h1 className="text-[28px] font-semibold text-fg">
            Hi, what&apos;s your plan for today?
          </h1>

          <div className="mt-7">
            <PillBar />
          </div>

          <div className="mt-5 w-full">
            <Composer
              placeholder="Aion CLI, Send a message, upload files, open a folder, or create a scheduled task…"
              modelLabel="Default Model"
              permissionLabel="Default"
              workInProject
            />
          </div>

          <div className="mt-12 w-full">
            <p className="text-center text-[13px] text-fg-muted">
              Select an assistant to start a task
            </p>
            <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {ASSISTANTS.map((a) => (
                <AssistantCard key={a.id} a={a} />
              ))}
            </div>
          </div>
        </div>
      </div>

      <FloatingFooter />
    </div>
  );
}
