"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import type { ScreenName, ThemeName } from "@/types";

interface AppState {
  theme: ThemeName;
  toggleTheme: () => void;
  setTheme: (t: ThemeName) => void;

  screen: ScreenName;
  activeConversationId: string | null;
  openConversation: (id: string) => void;
  goHome: () => void;
  goScheduled: () => void;
  goSettings: () => void;

  settingsSection: string;
  setSettingsSection: (s: string) => void;

  sidebarCollapsed: boolean;
  toggleSidebar: () => void;

  searchOpen: boolean;
  setSearchOpen: (v: boolean) => void;
}

const Ctx = createContext<AppState | null>(null);

export function useApp() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useApp must be used within AppProvider");
  return ctx;
}

function applyTheme(theme: ThemeName) {
  const root = document.documentElement;
  root.classList.toggle("dark", theme === "dark");
  root.setAttribute("data-theme", theme);
  try {
    localStorage.setItem("__aionui_theme", theme);
  } catch {
    /* ignore */
  }
}

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<ThemeName>("dark");
  const [screen, setScreen] = useState<ScreenName>("home");
  const [activeConversationId, setActiveConversationId] = useState<string | null>(
    null,
  );
  const [settingsSection, setSettingsSection] = useState("model");
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);

  // sync initial theme from the DOM (set by the no-flash bootstrap script)
  // and default the sidebar to collapsed on small screens.
  useEffect(() => {
    // Sync React state to the pre-hydration DOM/localStorage set by the
    // no-flash bootstrap script (an external system), and collapse the sidebar
    // on small screens. This intentionally runs once on mount.
    const current = document.documentElement.classList.contains("dark")
      ? "dark"
      : "light";
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setThemeState(current);
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (window.innerWidth < 768) setSidebarCollapsed(true);
  }, []);

  const setTheme = useCallback((t: ThemeName) => {
    setThemeState(t);
    applyTheme(t);
  }, []);

  const toggleTheme = useCallback(() => {
    setThemeState((prev) => {
      const next = prev === "dark" ? "light" : "dark";
      applyTheme(next);
      return next;
    });
  }, []);

  const value = useMemo<AppState>(
    () => ({
      theme,
      toggleTheme,
      setTheme,
      screen,
      activeConversationId,
      openConversation: (id) => {
        setActiveConversationId(id);
        setScreen("conversation");
      },
      goHome: () => {
        setScreen("home");
        setActiveConversationId(null);
      },
      goScheduled: () => setScreen("scheduled"),
      goSettings: () => setScreen("settings"),
      settingsSection,
      setSettingsSection,
      sidebarCollapsed,
      toggleSidebar: () => setSidebarCollapsed((v) => !v),
      searchOpen,
      setSearchOpen,
    }),
    [
      theme,
      toggleTheme,
      setTheme,
      screen,
      activeConversationId,
      settingsSection,
      sidebarCollapsed,
      searchOpen,
    ],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}
