"use client";

import { cn } from "@/lib/utils";
import {
  ArrowLeftIcon,
  ArrowRightIcon,
  CollapseIcon,
  PanelRightIcon,
} from "@/components/icons";
import { useApp } from "./AppContext";

function TbButton({
  children,
  onClick,
  disabled,
  label,
}: {
  children: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  label: string;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      onClick={onClick}
      disabled={disabled}
      className={cn(
        "flex h-7 w-7 items-center justify-center rounded-[6px] text-fg-secondary transition-colors",
        disabled
          ? "cursor-default text-fg-disabled"
          : "hover:bg-bg-hover hover:text-fg",
      )}
    >
      {children}
    </button>
  );
}

export function TitleBar() {
  const { toggleSidebar, screen } = useApp();

  return (
    <div className="app-titlebar relative z-10 flex h-9 shrink-0 items-center justify-between gap-2 border-b border-border-base bg-bg-2 px-2">
      <div className="flex items-center gap-0.5">
        <TbButton label="Collapse" onClick={toggleSidebar}>
          <CollapseIcon size={16} />
        </TbButton>
        <TbButton label="Back" disabled>
          <ArrowLeftIcon size={16} />
        </TbButton>
        <TbButton label="Forward" disabled>
          <ArrowRightIcon size={16} />
        </TbButton>
      </div>

      <div className="pointer-events-none flex-1 text-center text-[13px] font-semibold text-fg" />

      <div className="flex items-center gap-1">
        {screen === "conversation" && (
          <TbButton label="Toggle panel">
            <PanelRightIcon size={16} />
          </TbButton>
        )}
      </div>
    </div>
  );
}
