"use client";

import { AppProvider, useApp } from "./AppContext";
import { TitleBar } from "./TitleBar";
import { Sidebar } from "./Sidebar";
import { SettingsSidebar } from "./SettingsSidebar";
import { SearchOverlay } from "./SearchOverlay";
import { HomeScreen } from "./screens/HomeScreen";
import { ConversationScreen } from "./screens/ConversationScreen";
import { ScheduledScreen } from "./screens/ScheduledScreen";
import { SettingsScreen } from "./screens/SettingsScreen";

function Content() {
  const { screen } = useApp();
  switch (screen) {
    case "conversation":
      return <ConversationScreen />;
    case "scheduled":
      return <ScheduledScreen />;
    case "settings":
      return <SettingsScreen />;
    case "home":
    default:
      return <HomeScreen />;
  }
}

function Shell() {
  const { screen } = useApp();
  return (
    <div className="app-shell flex h-screen min-h-0 w-full flex-col bg-bg-1">
      <TitleBar />
      <section className="layout flex min-h-0 flex-1">
        {screen === "settings" ? <SettingsSidebar /> : <Sidebar />}
        <main className="layout-content flex min-w-0 flex-1 flex-col overflow-hidden bg-bg-1">
          <Content />
        </main>
      </section>
      <SearchOverlay />
    </div>
  );
}

export function AppShell() {
  return (
    <AppProvider>
      <Shell />
    </AppProvider>
  );
}
